{"cards": [{"node_code": "N_03d9c3da13264a58", "definition": "研究道路车辆承载骨架（车架/车身结构）及车桥系统的结构强度、刚度、轻量化设计及底盘总体布局与集成技术。", "boundary": "聚焦于车辆静态与动态载荷下的结构承载体系。涵盖纵置/横置/承载式/非承载式车架、前后车桥、副车架及底盘各部件的空间布置与连接。与悬架的区别在于本节点侧重刚性承载结构，而非弹性连接；与转向/制动的区别在于本节点侧重基础支撑平台，而非主动控制执行机构。", "includes": ["车架、车身结构及副车架的设计、分析与轻量化", "前/后车桥（整体式/独立式）的结构设计与强度校核", "底盘总体布置、零部件连接及NVH基础结构特性"], "excludes": ["悬架弹簧、减振器等弹性元件及其调校（归入悬架、减振与行驶平顺性）", "转向机、制动卡钳等主动控制部件（归入转向或制动系统）"], "sibling_distinctions": [{"other_code": "N_2076cba5e2f81fff", "rule": "本节点收录刚性承载结构（车架、车桥）；兄弟节点收录连接车轮与车桥的弹性/阻尼元件（悬架、减振器）。"}, {"other_code": "N_7da3cc50edb79099", "rule": "本节点收录车辆内部支撑结构；兄弟节点收录车轮、轮胎及与路面接触的界面特性。"}], "cross_boundary_rule": "若研究车架材料本身的微观组织或通用焊接工艺，可关联至“工程材料”或“制造工艺”；若研究车架在整车动力学中的载荷传递或特定车型的结构优化，主挂载至本节点。"}, {"node_code": "N_7da3cc50edb79099", "definition": "研究车轮总成、轮胎结构特性及其与路面接触界面的力学行为，包括滚动阻力、抓地力、噪声及磨损机理。", "boundary": "聚焦于车辆与地面接触的最末端系统。涵盖轮胎结构（胎体、带束层）、轮辋设计、轮胎-路面摩擦模型、滚动阻力及胎噪机理。与悬架的区别在于本节点侧重接触界面与滚动特性，而非垂直振动隔离；与底盘结构的区别在于本节点侧重可旋转部件及接触力学。", "includes": ["轮胎结构设计、材料特性及滚动阻力/抓地力分析", "轮辋、轮毂及车轮总成的强度与平衡设计", "轮胎-路面相互作用（Tire-Road Interaction）模型及噪声振动研究"], "excludes": ["悬架弹簧与减振器（归入悬架、减振与行驶平顺性）", "车架与车桥的刚性结构（归入车架、车桥与底盘系统）"], "sibling_distinctions": [{"other_code": "N_2076cba5e2f81fff", "rule": "本节点收录车轮轮胎及路面接触特性；兄弟节点收录连接车轮与车身的悬架系统及平顺性控制。"}, {"other_code": "N_03d9c3da13264a58", "rule": "本节点收录旋转部件及接触界面；兄弟节点收录固定或半固定的承载骨架结构。"}], "cross_boundary_rule": "若研究轮胎橡胶材料的通用高分子特性，可关联至“工程材料”；若研究轮胎在特定路面下的动力学响应、磨损或噪声对整车的影响，主挂载至本节点。"}, {"node_code": "N_2076cba5e2f81fff", "definition": "研究连接车轮与车身的悬架系统、减振元件及其动力学特性，重点在于行驶平顺性、操纵稳定性及NVH性能优化。", "boundary": "聚焦于车辆垂直及侧向振动的隔离与控制。涵盖螺旋弹簧、空气弹簧、减振器、稳定杆等元件的设计与调校，以及悬架运动学/动力学分析。与车架的区别在于本节点侧重弹性连接与能量耗散，而非刚性承载；与转向/制动的区别在于本节点侧重被动/半主动振动控制，而非主动轨迹/速度控制。", "includes": ["悬架结构（麦弗逊、多连杆等）设计与运动学/动力学分析", "减振器、弹簧、稳定杆等元件的特性匹配与调校", "行驶平顺性、车身姿态控制及悬架NVH性能研究"], "excludes": ["车架、车桥等刚性承载结构（归入车架、车桥与底盘系统）", "轮胎与路面的接触力学（归入车轮、轮胎与路面相互作用）"], "sibling_distinctions": [{"other_code": "N_03d9c3da13264a58", "rule": "本节点收录弹性/阻尼连接系统；兄弟节点收录刚性承载骨架。"}, {"other_code": "N_7da3cc50edb79099", "rule": "本节点收录车身与车轮间的振动隔离；兄弟节点收录车轮与路面间的接触特性。"}], "cross_boundary_rule": "若研究减振器内部液压油的通用流变特性，可关联至“热流体与能源动力工程”；若研究悬架参数对整车平顺性或操控性的影响及系统级调校，主挂载至本节点。"}]}
